# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DESCRIBING PERSONALITY AND CHARACTER (ENG.6.3)</text>\n  <rect x="20" y="46" width="210" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Positive Traits (Olumlu)</text>\n  <text x="32" y="96" font-size="11.5" fill="#1e3a8a">• polite (kibar) · helpful (yardımsever)</text>\n  <text x="32" y="118" font-size="11.5" fill="#1e3a8a">• patient (sabırlı) · caring (şefkatli)</text>\n  <text x="32" y="140" font-size="11.5" fill="#1e3a8a">• clever / brilliant (zeki / parlak)</text>\n  <text x="32" y="162" font-size="11.5" fill="#1e3a8a">• organised / tidy (düzenli / tertipli)</text>\n  <text x="32" y="184" font-size="11.5" fill="#1e3a8a">• focused · independent · social</text>\n  <text x="125" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">She seems polite and caring.</text>\n\n  <rect x="245" y="46" width="210" height="194" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">Other Traits &amp; Questions</text>\n  <text x="257" y="96" font-size="11.5" fill="#831843">• rude (kaba) ↔ polite (kibar)</text>\n  <text x="257" y="118" font-size="11.5" fill="#831843">• lazy (tembel) ↔ hardworking</text>\n  <text x="257" y="140" font-size="11.5" fill="#831843">• shy (utangaç) ↔ social (sosyal)</text>\n  <text x="257" y="162" font-size="11.5" fill="#831843">• serious (ciddi) · crazy (çılgın)</text>\n  <text x="257" y="188" font-size="11" font-weight="bold" fill="#9d174d">Q: What is he like? (Karakteri)</text>\n  <text x="257" y="206" font-size="11" font-weight="bold" fill="#9d174d">Q: What does he look like? (Dış)</text>\n\n  <rect x="470" y="46" width="210" height="194" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Social Language in Use</text>\n  <text x="482" y="98" font-size="11" font-weight="bold" fill="#854d0e">• You\'re full of beans!</text>\n  <text x="482" y="116" font-size="10.5" fill="#713f12">  (Bugün çok enerjiksin / kıpır kıpırsın!)</text>\n  <text x="482" y="142" font-size="11" font-weight="bold" fill="#854d0e">• Just keep your cool!</text>\n  <text x="482" y="160" font-size="10.5" fill="#713f12">  (Panik yapma, sakinliğini koru!)</text>\n  <text x="482" y="186" font-size="11" font-weight="bold" fill="#854d0e">• Stop showing off!</text>\n  <text x="482" y="204" font-size="10.5" fill="#713f12">  (Gösteriş yapmayı bırak, bilmiş seni!)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CLOTHING, ACCESSORIES AND POSSESSION (WHOSE / HAVE GOT)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Clothes &amp; Accessories by Season</text>\n  <text x="36" y="98" font-size="11.5" fill="#14532d">• Summer: swimsuit (mayo), shorts, T-shirt, sunglasses</text>\n  <text x="36" y="122" font-size="11.5" fill="#14532d">• Winter: coat (mont), sweater, scarf, gloves, boots</text>\n  <text x="36" y="146" font-size="11.5" fill="#14532d">• Sports &amp; Daily: trainers (spor ayakkabı), tights, kit</text>\n  <text x="36" y="170" font-size="11.5" fill="#14532d">• Jewellery: necklace (kolye), bracelet (bileklik), chain</text>\n  <text x="36" y="194" font-size="11.5" fill="#14532d">• Belongings: wallet (cüzdan), purse (el çantası), pocket</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Body parts: knee (diz), ankle (ayak bileği), back, leg</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Whose ...? &amp; Have / Has Got</text>\n  <text x="376" y="98" font-size="11.5" font-weight="bold" fill="#581c87">1. Asking about ownership (Whose):</text>\n  <text x="376" y="118" font-size="11.5" fill="#6b21a8">• Whose wallet is this? ➔ It is Emre\'s wallet.</text>\n  <text x="376" y="138" font-size="11.5" fill="#6b21a8">• Whose trainers are these? ➔ They are mine.</text>\n  <text x="376" y="164" font-size="11.5" font-weight="bold" fill="#581c87">2. Expressing possession (Have / Has got):</text>\n  <text x="376" y="184" font-size="11.5" fill="#6b21a8">• I / You / We / They have got a new sports kit.</text>\n  <text x="376" y="204" font-size="11.5" fill="#6b21a8">• He / She has got curly hair and a silver necklace.</text>\n  <text x="520" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">Negative: haven\'t got / hasn\'t got</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PRESENT CONTINUOUS VS. SIMPLE PRESENT &amp; COMPARISONS</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Simple Present vs. Present Continuous</text>\n  <text x="40" y="98" font-size="11.5" font-weight="bold" fill="#155e75">• Simple Present (Routines &amp; Habits):</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  every day, usually, always, on Mondays</text>\n  <text x="40" y="134" font-size="11" fill="#0e7490">  «She usually wears a uniform at school.»</text>\n  <text x="40" y="160" font-size="11.5" font-weight="bold" fill="#155e75">• Present Continuous (Right Now):</text>\n  <text x="40" y="178" font-size="11" fill="#334155">  now, right now, at the moment, today</text>\n  <text x="40" y="196" font-size="11" fill="#0e7490">  «Today she is wearing trainers and tights.»</text>\n  <text x="182" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">wear / wears ↔ am / is / are wearing</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Comparative &amp; Superlative Adjectives</text>\n  <text x="375" y="98" font-size="11.5" fill="#9a3412">• Short Adjectives (-er / the -est):</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  tall ➔ taller than ➔ the tallest</text>\n  <text x="375" y="138" font-size="11.5" fill="#9a3412">• Long Adjectives (more / the most):</text>\n  <text x="375" y="156" font-size="11" fill="#334155">  patient ➔ more patient than ➔ the most patient</text>\n  <text x="375" y="178" font-size="11.5" fill="#9a3412">• Irregular Adjectives (Düzensiz):</text>\n  <text x="375" y="196" font-size="11" fill="#334155">  good ➔ better ➔ the best · bad ➔ worse ➔ the worst</text>\n  <text x="517" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">Comparing 2 people vs. 3 or more people</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
